public class EffectDefinition
implements Closeable {
    private final Supplier<ResourceLocation> id = Suppliers.memoize(this::fetchId);
    private static final String GL_DEBUG_LABEL = "%s Begin Rendering Effeks".formatted("[AAAParticles]");
    private static final String GL_UNLOAD_MANAGER_LABEL = "%s Unloading Effekseer managers".formatted("[AAAParticles]");
    private final Supplier<String> glUnloadLabel = Suppliers.memoize(() -> "%s Unloading effek %s".formatted("[AAAParticles]", this.id.get()));
    private EffekseerEffect effect;
