public static void gc() {
    boolean enabled = (Boolean)AAAClientConfig.GC_ENABLE.get();
    if (!enabled) {
        return;
    }
    if (!EffectRegistry.isSystemAtLowFreeMem()) {
        return;
    }
    EffectRegistry.entries().stream().map(Map.Entry::getValue).filter(holder -> !holder.getMetadata().preload()).filter(EffectHolder::isPresent).sorted(Comparator.comparing(EffectHolder::getLastUsed)).limit(1L).forEach(EffectHolder::unload);
}

private static boolean isSystemAtLowFreeMem() {
    boolean lowFreeMem;
    Runtime runtime = Runtime.getRuntime();
    java.lang.management.OperatingSystemMXBean operatingSystemMXBean = ManagementFactory.getOperatingSystemMXBean();
    if (operatingSystemMXBean instanceof OperatingSystemMXBean) {
        OperatingSystemMXBean os = (OperatingSystemMXBean)operatingSystemMXBean;
        lowFreeMem = (double)os.getFreeMemorySize() / (double)runtime.maxMemory() <= 0.25;
    } else {
        MemoryMXBean bean = ManagementFactory.getMemoryMXBean();
        MemoryUsage heap = bean.getHeapMemoryUsage();
        MemoryUsage offh = bean.getNonHeapMemoryUsage();
        lowFreeMem = (double)(heap.getUsed() + offh.getUsed()) / (double)(heap.getMax() + offh.getMax()) <= 0.125;
    }
    return lowFreeMem;
}

